"""Lane 2/5: two BASE HUMAN MODELS as .glb (a male-proportioned and a female-proportioned stylised figure), generated by this code: low-poly, no face, no scan, no photo, no external asset,
so there is nothing to license from anyone (generated procedurally here; the repository's own licence decision applies, not a third party's).
The figure is built from tubes and one sphere and is split into THREE materials named ``skin``, ``top`` and ``bottom`` so the client can recolour clothes by changing two material colours,
and a few STYLE switches change which body parts are covered (tank / t-shirt / long sleeve, shorts / pants). It is a placeholder body for fitting rooms and previews: stylised, not realistic.
``extras`` on the scene node record that it is generated and not a person.
"""
from __future__ import annotations

import math
import struct
from typing import Any

from app.glb_tools import build_glb

SEXES = ("male", "female")
TOP_STYLES = ("tank", "tshirt", "longsleeve")
BOTTOM_STYLES = ("shorts", "pants")
SEG = 12                       # sides of every tube: low poly on purpose
Color = tuple[int, int, int]

# proportions in metres (height, shoulder half-width, chest/waist/hip half-widths and depths). The two presets are STYLISED proportions, not statements about any person.
PRESETS = {
    "male":   {"height": 1.78, "shoulder": 0.205, "chest": (0.165, 0.105), "waist": (0.140, 0.095), "hip": (0.150, 0.100), "arm": 0.040, "thigh": 0.085, "calf": 0.055, "head": 0.105},
    "female": {"height": 1.66, "shoulder": 0.175, "chest": (0.145, 0.095), "waist": (0.115, 0.085), "hip": (0.160, 0.105), "arm": 0.034, "thigh": 0.088, "calf": 0.050, "head": 0.098},
}


def _check_color(value: Any, name: str) -> Color:
    if not (isinstance(value, (tuple, list)) and len(value) == 3 and all(isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255 for c in value)):
        raise ValueError(f"{name} must be three integers from 0 to 255")
    return tuple(value)  # type: ignore[return-value]


class _Mesh:
    def __init__(self) -> None:
        self.pos: list[float] = []
        self.idx: list[int] = []

    def tube(self, stops: list[tuple[tuple[float, float, float], float, float]], cap: bool = True) -> None:
        """Rings along a polyline: each stop is (centre, half-width in x, half-depth in z). Rings are horizontal (the figure is upright), limbs are tilted by moving the centres."""
        base = len(self.pos) // 3
        for (cx, cy, cz), a, b in stops:
            for i in range(SEG):
                t = 2 * math.pi * i / SEG
                self.pos += [cx + a * math.cos(t), cy, cz + b * math.sin(t)]
        for r in range(len(stops) - 1):
            for i in range(SEG):
                j = (i + 1) % SEG
                p0, p1, q0, q1 = base + r * SEG + i, base + r * SEG + j, base + (r + 1) * SEG + i, base + (r + 1) * SEG + j
                self.idx += [p0, q0, p1, p1, q0, q1]
        if cap:
            for ring, up in ((0, False), (len(stops) - 1, True)):
                centre = len(self.pos) // 3
                (cx, cy, cz), _, _ = stops[ring]
                self.pos += [cx, cy, cz]
                for i in range(SEG):
                    j = (i + 1) % SEG
                    a, b = base + ring * SEG + i, base + ring * SEG + j
                    self.idx += [a, b, centre] if up else [b, a, centre]

    def sphere(self, centre: tuple[float, float, float], radius: float, rings: int = 6) -> None:
        stops = []
        for r in range(rings + 1):
            phi = math.pi * r / rings
            stops.append(((centre[0], centre[1] + radius * math.cos(phi), centre[2]), max(radius * math.sin(phi), 1e-4), max(radius * math.sin(phi), 1e-4) * 0.95))
        self.tube(stops, cap=False)


def build_base_model(sex: str = "male", top_style: str = "tshirt", bottom_style: str = "pants", skin: Color = (224, 172, 105), top: Color = (60, 90, 160), bottom: Color = (50, 50, 60)) -> bytes:
    if sex not in SEXES:
        raise ValueError(f"unknown sex preset {sex!r}")
    if top_style not in TOP_STYLES or bottom_style not in BOTTOM_STYLES:
        raise ValueError("unknown clothing style")
    colours = {"skin": _check_color(skin, "skin"), "top": _check_color(top, "top"), "bottom": _check_color(bottom, "bottom")}
    p = PRESETS[sex]
    h = p["height"]
    parts: dict[str, _Mesh] = {"skin": _Mesh(), "top": _Mesh(), "bottom": _Mesh()}
    hip_y, waist_y, chest_y, shoulder_y, neck_y = 0.52 * h, 0.60 * h, 0.70 * h, 0.81 * h, 0.835 * h
    # legs: thigh (hip -> knee), calf (knee -> ankle), foot. Two legs at +-x.
    knee_y, ankle_y = 0.28 * h, 0.04 * h
    leg_x = p["hip"][0] * 0.55
    for side in (-1, 1):
        thigh = [((side * leg_x, hip_y, 0.0), p["thigh"], p["thigh"]), ((side * leg_x * 0.95, knee_y, 0.0), p["thigh"] * 0.72, p["thigh"] * 0.72)]
        calf = [((side * leg_x * 0.95, knee_y, 0.0), p["calf"] * 1.15, p["calf"] * 1.15), ((side * leg_x * 0.9, ankle_y, 0.0), p["calf"] * 0.65, p["calf"] * 0.65)]
        foot = [((side * leg_x * 0.9, ankle_y, 0.0), p["calf"] * 0.7, p["calf"] * 0.8), ((side * leg_x * 0.9, 0.0, 0.05), p["calf"] * 0.75, p["calf"] * 1.6)]
        parts["bottom"].tube(thigh)
        if bottom_style == "pants":
            parts["bottom"].tube(calf)
        else:
            parts["skin"].tube(calf)
        parts["skin"].tube(foot)
    # torso: hips + waist belong to the bottom, chest to the top
    parts["bottom"].tube([((0, hip_y, 0), p["hip"][0], p["hip"][1]), ((0, waist_y, 0), p["waist"][0], p["waist"][1])])
    parts["top"].tube([((0, waist_y, 0), p["waist"][0], p["waist"][1]), ((0, chest_y, 0), p["chest"][0], p["chest"][1]), ((0, shoulder_y, 0), p["shoulder"] * 0.72, p["chest"][1] * 0.92)])
    parts["skin"].tube([((0, shoulder_y, 0), p["shoulder"] * 0.30, p["chest"][1] * 0.5), ((0, neck_y, 0), 0.045, 0.045), ((0, neck_y + 0.04, 0), 0.04, 0.04)])
    parts["skin"].sphere((0.0, neck_y + 0.04 + p["head"], 0.0), p["head"])
    # arms hang slightly away from the body: shoulder -> elbow -> wrist -> hand
    for side in (-1, 1):
        sx = side * p["shoulder"] * 0.95
        upper = [((sx, shoulder_y - 0.02, 0.0), p["arm"] * 1.3, p["arm"] * 1.3), ((side * (p["shoulder"] + 0.04), shoulder_y - 0.22 * h, 0.0), p["arm"] * 1.0, p["arm"] * 1.0)]
        lower = [((side * (p["shoulder"] + 0.04), shoulder_y - 0.22 * h, 0.0), p["arm"] * 0.95, p["arm"] * 0.95), ((side * (p["shoulder"] + 0.07), shoulder_y - 0.42 * h, 0.02), p["arm"] * 0.7, p["arm"] * 0.7)]
        hand = [((side * (p["shoulder"] + 0.07), shoulder_y - 0.42 * h, 0.02), p["arm"] * 0.75, p["arm"] * 0.6), ((side * (p["shoulder"] + 0.08), shoulder_y - 0.49 * h, 0.03), p["arm"] * 0.55, p["arm"] * 0.45)]
        (parts["skin"] if top_style == "tank" else parts["top"]).tube(upper)
        (parts["top"] if top_style == "longsleeve" else parts["skin"]).tube(lower)
        parts["skin"].tube(hand)
    return _write(parts, colours, sex, top_style, bottom_style)


def _write(parts: dict[str, _Mesh], colours: dict[str, Color], sex: str, top_style: str, bottom_style: str) -> bytes:
    binary, views, accessors, primitives, materials = b"", [], [], [], []

    def add(blob: bytes) -> int:
        nonlocal binary
        binary += b"\x00" * (-len(binary) % 4)
        views.append({"buffer": 0, "byteOffset": len(binary), "byteLength": len(blob)})
        binary += blob
        return len(views) - 1
    for name in ("skin", "top", "bottom"):
        mesh = parts[name]
        if not mesh.idx:
            continue
        xs, ys, zs = mesh.pos[0::3], mesh.pos[1::3], mesh.pos[2::3]
        v_pos = add(struct.pack(f"<{len(mesh.pos)}f", *mesh.pos))
        v_idx = add(struct.pack(f"<{len(mesh.idx)}H", *mesh.idx))
        accessors += [{"bufferView": v_pos, "componentType": 5126, "count": len(mesh.pos) // 3, "type": "VEC3", "min": [min(xs), min(ys), min(zs)], "max": [max(xs), max(ys), max(zs)]},
                      {"bufferView": v_idx, "componentType": 5123, "count": len(mesh.idx), "type": "SCALAR"}]
        materials.append({"name": name, "doubleSided": True, "pbrMetallicRoughness": {"baseColorFactor": [c / 255 for c in colours[name]] + [1.0], "metallicFactor": 0.0, "roughnessFactor": 0.85}})
        primitives.append({"attributes": {"POSITION": len(accessors) - 2}, "indices": len(accessors) - 1, "material": len(materials) - 1})
    doc = {"asset": {"version": "2.0", "generator": "ai-creator-studio base_models"}, "scene": 0, "scenes": [{"nodes": [0]}],
           "nodes": [{"name": f"base_{sex}", "mesh": 0, "extras": {"generated_by_code": True, "is_scan": False, "is_a_real_person": False, "has_face_detail": False, "sex_preset": sex,
                                                                 "top_style": top_style, "bottom_style": bottom_style, "licence": "generated by this repository's code; no third-party asset"}}],
           "meshes": [{"name": f"base_{sex}", "primitives": primitives}], "materials": materials, "accessors": accessors, "bufferViews": views, "buffers": [{"byteLength": len(binary)}]}
    return build_glb(doc, binary)
